package org.tangowiz.app
import android.app.*
import android.content.*
import android.os.*
import android.view.*
import android.view.accessibility.AccessibilityNodeInfo
import android.widget.*
import org.json.JSONObject
import java.io.*
import java.security.MessageDigest
import java.util.concurrent.CopyOnWriteArrayList

object ExportUiValidation{
 fun run(i:Instrumentation){val ctx=i.targetContext;val fixture=File(Store(ctx).root,"export-ui-fixture/three-hour.wav");var activity:Activity?=null;val states=CopyOnWriteArrayList<ExportState>();val observe:()->Unit={states+=ExportJobs.state;if(ExportJobs.state.kind=="scanning"){ExportJobs.prepare(ctx);ExportJobs.prepare(ctx)}}
  fun await(test:()->Boolean){val until=SystemClock.elapsedRealtime()+90000;while(!test()){check(SystemClock.elapsedRealtime()<until){"Export timed out: ${ExportJobs.state}"};SystemClock.sleep(50)};i.waitForIdleSync()}
  fun find(view:View,description:String):View?{if(view.contentDescription?.toString()==description)return view;if(view is ViewGroup)for(n in 0 until view.childCount)find(view.getChildAt(n),description)?.let{return it};return null}
  try{check(!ExportService.isBusy());fixture.parentFile!!.mkdirs();val reusable=File(ctx.filesDir,"export-store-test/logs/synthetic-three-hours/microphone-0.wav");if(reusable.isFile)reusable.inputStream().use{input->fixture.outputStream().buffered(262144).use{input.copyTo(it,262144)}} else RandomAccessFile(fixture,"rw").use{it.setLength(172800044);it.fd.sync()};val original=fixture.length();ExportJobs.restore(ctx);ExportJobs.publish(ctx,ExportState());ExportJobs.listeners.add(observe)
   activity=i.startActivitySync(Intent(ctx,MainActivity::class.java).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));check(find(activity!!.window.decorView,"Export recordings and diagnostics")==null);i.runOnMainSync{check(find(activity!!.window.decorView,"More options")!!.performClick())}
   await{i.uiAutomation.rootInActiveWindow?.findAccessibilityNodeInfosByText("Export debug info")?.isNotEmpty()==true};var menu:AccessibilityNodeInfo?=null;await{menu=i.uiAutomation.rootInActiveWindow?.findAccessibilityNodeInfosByText("Export debug info")?.firstOrNull();menu!=null};val bounds=android.graphics.Rect();menu!!.getBoundsInScreen(bounds);i.uiAutomation.executeShellCommand("input tap ${bounds.centerX()} ${bounds.centerY()}").close()
   await{SetupProbe.resumed is ExportActivity};activity=SetupProbe.resumed;check(ExportActivity::class.java.getDeclaredField("share").apply{isAccessible=true}.get(activity) is ImageButton)
   await{ExportJobs.state.kind=="preparing"};val before=activity;i.runOnMainSync{activity!!.recreate()};await{SetupProbe.resumed is ExportActivity&&SetupProbe.resumed!==before};activity=SetupProbe.resumed;await{!ExportJobs.state.busy&&ExportJobs.state.kind=="ready"};check(states.any{it.kind=="scanning"});check(states.any{it.kind=="preparing"&&it.total>=original-1&&it.totalFiles>0});check(fixture.length()==original);val source=ExportJobs.file(ctx)!!;check(source.length()>0)
   val share=find(activity!!.window.decorView,"Share ZIP")!!;val save=find(activity!!.window.decorView,"Save ZIP")!!;await{share.isShown&&save.isShown}
   var shared:Intent?=null;val monitor=object:Instrumentation.ActivityMonitor(){override fun onStartActivity(intent:Intent):Instrumentation.ActivityResult?{if(intent.action==Intent.ACTION_CHOOSER){shared=intent;return Instrumentation.ActivityResult(Activity.RESULT_CANCELED,null)};return null}};i.addMonitor(monitor);i.runOnMainSync{share.performClick()};i.waitForIdleSync();i.removeMonitor(monitor)
   val send=shared!!.getParcelableExtra<Intent>(Intent.EXTRA_INTENT)!!;val uri=send.getParcelableExtra<android.net.Uri>(Intent.EXTRA_STREAM)!!;check(send.action==Intent.ACTION_SEND&&send.type=="application/zip"&&send.flags and Intent.FLAG_GRANT_READ_URI_PERMISSION!=0&&send.clipData!!.getItemAt(0).uri==uri);check(ctx.contentResolver.getType(uri)=="application/zip")
   i.runOnMainSync{save.performClick()};await{i.uiAutomation.rootInActiveWindow?.packageName?.toString()?.contains("documentsui")==true};i.uiAutomation.serviceInfo=i.uiAutomation.serviceInfo.apply{flags=flags or android.accessibilityservice.AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS}
   var saved=false;val until=SystemClock.elapsedRealtime()+20000;while(!saved&&SystemClock.elapsedRealtime()<until){val root=i.uiAutomation.rootInActiveWindow;if(root!=null){val nodes=listOf("com.google.android.documentsui:id/button_create","com.android.documentsui:id/button_create").flatMap{root.findAccessibilityNodeInfosByViewId(it)};val button=nodes.firstOrNull{it.isEnabled}?:root.findAccessibilityNodeInfosByText("Save").firstOrNull{it.isClickable&&it.isEnabled};if(button!=null)saved=button.performAction(AccessibilityNodeInfo.ACTION_CLICK)};if(!saved)SystemClock.sleep(100)};check(saved){"Could not choose Save in DocumentsUI"}
   await{ExportJobs.state.kind=="ready"&&ExportJobs.state.error=="ZIP saved"};val destination=android.net.Uri.parse(ctx.getSharedPreferences("export-status",0).getString("last_saved_uri",null)!!)
   fun digest(input:InputStream):String{val sha=MessageDigest.getInstance("SHA-256");input.use{val b=ByteArray(262144);while(true){val n=it.read(b);if(n<0)break;sha.update(b,0,n)}};return sha.digest().joinToString(""){"%02x".format(it)}}
   check(digest(source.inputStream())==digest(ctx.contentResolver.openInputStream(destination)!!));fixture.delete();fixture.parentFile!!.delete();ExportJobs.listeners.remove(observe);i.runOnMainSync{activity!!.finishAndRemoveTask()}
   val report=JSONObject().put("status","passed").put("menu_opens_separate_activity",true).put("synthetic_input_bytes",original).put("visible_scanning_and_inventory_progress",true).put("repeated_prepare_single_job",true).put("activity_recreation_keeps_one_job",true).put("standard_icon_actions",true).put("share_clipdata_and_read_grant",true).put("actual_documentsui_save_hash_matches",true).put("file",source.name).put("zip_bytes",source.length());File(ctx.filesDir,"export-ui-validation.json").writeText(report.toString(2));i.finish(0,Bundle().apply{putString("summary",report.toString())})
  }catch(e:Throwable){ExportJobs.listeners.remove(observe);runCatching{i.runOnMainSync{activity?.finishAndRemoveTask()}};fixture.delete();fixture.parentFile?.delete();File(ctx.filesDir,"export-ui-validation.json").writeText(JSONObject().put("status","failed").put("error",e.stackTraceToString()).toString(2));i.finish(1,Bundle().apply{putString("error",e.stackTraceToString())})}
 }
 fun reopen(i:Instrumentation){try{val ctx=i.targetContext;ExportJobs.restore(ctx);val file=ExportJobs.file(ctx)!!;val uri=ExportJobs.uri(file);ctx.contentResolver.query(uri,arrayOf(android.provider.OpenableColumns.DISPLAY_NAME,android.provider.OpenableColumns.SIZE),null,null,null)!!.use{check(it.moveToFirst()&&it.getString(0)==file.name&&it.getLong(1)==file.length())};ctx.contentResolver.openInputStream(uri)!!.use{check(it.read()==0x50&&it.read()==0x4b)};check(runCatching{ctx.contentResolver.openOutputStream(uri,"w")}.isFailure);val report=JSONObject().put("status","passed").put("fresh_process_provider_read",true).put("restored_completed_zip",file.name).put("provider_write_denied",true);File(ctx.filesDir,"export-reopen-validation.json").writeText(report.toString(2));i.finish(0,Bundle().apply{putString("summary",report.toString())})}catch(e:Throwable){i.finish(1,Bundle().apply{putString("error",e.stackTraceToString())})}}
}
